insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-338', 'enf', null, 'No atendimento à mulher em situação de violência, a conduta da equipe de enfermagem inclui:', '["acolhimento qualificado, registro das informações, articulação com a rede de atenção e adoção das medidas previstas, como notificação.","registro apenas dos achados clínicos, sem incluir os relatos da mulher.","substituição do relato da mulher pela interpretação técnica da equipe.","comunicação dos casos apenas após a conclusão da investigação policial.","encerramento do acompanhamento após o encaminhamento à rede."]'::jsonb, 0, 'O relato da mulher deve ser registrado com suas próprias palavras; a notificação é compulsória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-339', 'enf', null, 'Durante as ações de promoção da saúde da mulher na Atenção Primária, a equipe participa do rastreamento dos cânceres do colo do útero e de mama. Considerando as recomendações vigentes, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-340', 'enf', null, 'A violência obstétrica inclui práticas como:', '["realização de procedimentos sem consentimento, como episiotomia de rotina, manobra de Kristeller e restrição injustificada de acompanhante.","oferta de métodos não farmacológicos de alívio da dor.","garantia de acompanhante de livre escolha.","estímulo ao contato pele a pele.","informação à mulher sobre os procedimentos."]'::jsonb, 0, 'A assistência deve respeitar a autonomia, a dignidade e os direitos da mulher.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-341', 'enf', null, 'Na consulta de enfermagem no climatério, uma orientação adequada para o alívio dos fogachos (ondas de calor) é:', '["usar roupas leves em camadas, evitar bebidas alcoólicas, cafeína e alimentos muito condimentados, praticar atividade física e procurar avaliação para tratamento, se necessário.","suspender toda atividade física.","usar roupas pesadas para evitar mudanças de temperatura.","iniciar terapia hormonal por conta própria.","aumentar o consumo de álcool à noite."]'::jsonb, 0, 'A terapia hormonal depende de avaliação individual de riscos e benefícios.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-342', 'enf', null, 'Gestante de 32 semanas refere diminuição dos movimentos fetais nas últimas 12 horas. A conduta adequada é:', '["orientar a procura imediata do serviço para avaliação da vitalidade fetal.","orientar repouso e aguardar a próxima consulta mensal.","orientar a ingestão de doces e aguardar uma semana.","considerar normal no terceiro trimestre.","suspender o pré-natal."]'::jsonb, 0, 'A redução dos movimentos fetais é sinal de alerta na gestação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-343', 'enf', null, 'O registro da altura uterina na curva do Cartão da Gestante permite:', '["acompanhar o crescimento fetal e identificar desvios, como restrição de crescimento ou excesso de líquido amniótico.","definir o sexo do bebê.","diagnosticar diabetes gestacional.","substituir a ultrassonografia em todos os casos.","determinar o tipo sanguíneo fetal."]'::jsonb, 0, 'Valores fora da faixa esperada devem ser investigados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-344', 'enf', null, 'No acompanhamento da gestação de alto risco, segundo a lógica da Rede Alyne e das linhas de cuidado, a gestante:', '["deve manter o acompanhamento compartilhado entre a Atenção Básica e o ambulatório de gestação de alto risco.","deve ser desligada da Atenção Básica após o encaminhamento.","deve ser acompanhada exclusivamente pela maternidade.","perde o direito à vinculação com a maternidade.","não precisa de consultas de enfermagem."]'::jsonb, 0, 'A Atenção Básica coordena o cuidado e mantém o vínculo com a gestante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-345', 'enf', null, 'Durante a assistência à parturiente, o enfermeiro obstetra identifica a necessidade de episiotomia. Segundo a Lei nº 7.498/1986, a realização de episiotomia e episiorrafia, com aplicação de anestesia local quando necessária, é atribuição:', '["da enfermeira obstétrica (ou obstetriz).","de qualquer técnico de enfermagem.","de qualquer enfermeiro, sem especialização.","do auxiliar de enfermagem.","exclusivamente do médico anestesista."]'::jsonb, 0, 'Deve ser feita apenas quando indicada, nunca de rotina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-346', 'enf', null, 'Na consulta de planejamento reprodutivo, a mulher de 36 anos, tabagista de 20 cigarros por dia, solicita anticoncepcional oral combinado. A conduta adequada é:', '["orientar que o método é contraindicado em sua situação e oferecer alternativas, como DIU, métodos com progestagênio isolado e preservativo.","prescrever o anticoncepcional combinado em dose dobrada.","orientar a parar de fumar e iniciar o método no mesmo dia, sem avaliação.","negar qualquer método contraceptivo.","orientar apenas a tabelinha."]'::jsonb, 0, 'Mulheres com 35 anos ou mais que fumam 15 cigarros ou mais por dia não devem usar contraceptivos com estrogênio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-347', 'enf', null, 'A anticoncepção de emergência deve ser orientada como método:', '["de uso eventual, após relação desprotegida ou falha do método, e não como contraceptivo de rotina.","de uso diário.","que interrompe gestação já implantada.","que protege contra IST.","que deve ser usado apenas por adolescentes."]'::jsonb, 0, 'Quanto mais cedo for tomada, maior a eficácia (até 5 dias após a relação).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-348', 'enf', null, 'No atendimento à gestante com convulsão por eclâmpsia, as medidas iniciais incluem:', '["proteger a paciente de lesões, manter a via aérea pérvia, lateralizá-la, oferecer oxigênio e administrar sulfato de magnésio conforme prescrição.","conter a gestante em decúbito dorsal e introduzir objeto na boca.","administrar diazepam como primeira escolha em todos os casos.","aguardar o término espontâneo da crise sem intervenção.","induzir o vômito."]'::jsonb, 0, 'O sulfato de magnésio é o anticonvulsivante de escolha na eclâmpsia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-349', 'enf', null, 'No acompanhamento pré-natal, a solicitação do teste de tolerância oral à glicose entre 24 e 28 semanas está indicada para gestantes:', '["com glicemia de jejum inicial inferior a 92 mg/dL, para rastreamento do diabetes gestacional, quando houver viabilidade financeira e técnica.","já diagnosticadas com diabetes prévio.","apenas acima de 40 anos.","apenas com sintomas de diabetes.","somente no puerpério."]'::jsonb, 0, 'Valores de jejum de 92 a 125 mg/dL no início da gestação já confirmam diabetes gestacional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-350', 'enf', null, 'Durante a amamentação, a puérpera relata dor intensa e presença de fissura no mamilo. A orientação prioritária é:', '["avaliar e corrigir a pega e o posicionamento, iniciar a mamada pela mama menos dolorida e manter a amamentação.","suspender a amamentação na mama afetada por uma semana.","aplicar álcool nos mamilos.","usar protetores de silicone permanentemente.","oferecer fórmula até a cicatrização."]'::jsonb, 0, 'A correção da pega é a principal medida para resolver e prevenir fissuras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-351', 'enf', null, 'No puerpério, a puérpera que fez cesariana deve ser orientada quanto à ferida operatória a:', '["manter a incisão limpa e seca, observar sinais de infecção (vermelhidão, secreção, febre) e procurar a unidade se surgirem.","não tomar banho por 15 dias.","aplicar pomada caseira diariamente.","evitar qualquer movimentação até a retirada dos pontos.","cobrir a incisão com plástico durante o dia todo."]'::jsonb, 0, 'A deambulação precoce e a higiene adequada favorecem a recuperação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-352', 'enf', null, 'A visita domiciliar à puérpera e ao recém-nascido na primeira semana após a alta tem como objetivos, EXCETO:', '["realizar a coleta do citopatológico do colo do útero de rotina.","avaliar o estado de saúde da mulher e do recém-nascido.","apoiar o aleitamento materno.","orientar cuidados com o coto umbilical.","verificar a realização da triagem neonatal e das vacinas."]'::jsonb, 0, 'O citopatológico não faz parte da avaliação da primeira semana pós-parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-353', 'enf', null, 'Durante as consultas de acompanhamento do crescimento e do desenvolvimento infantil, a equipe utiliza a Caderneta da Criança para registrar as informações das avaliações periódicas. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-354', 'enf', null, 'Na avaliação do estado nutricional infantil com as curvas da OMS, uma criança com peso para a idade abaixo do escore-z -2 e acima do escore-z -3 é classificada com:', '["baixo peso para a idade.","peso adequado para a idade.","muito baixo peso para a idade.","peso elevado para a idade.","obesidade."]'::jsonb, 0, 'Abaixo de -3: muito baixo peso para a idade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-355', 'enf', null, 'Na estratégia AIDPI, a criança de 2 meses a 5 anos com tosse ou dificuldade para respirar que apresenta tiragem subcostal deve ser classificada como:', '["pneumonia grave ou doença muito grave, com referência urgente.","não é pneumonia: tosse ou resfriado.","pneumonia sem gravidade, com tratamento domiciliar.","asma leve.","infecção de ouvido."]'::jsonb, 0, 'Tiragem subcostal e sinais gerais de perigo indicam gravidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-356', 'enf', null, 'Na AIDPI, a criança com diarreia e presença de sangue nas fezes é classificada como:', '["disenteria.","diarreia persistente.","desidratação grave.","diarreia sem desidratação.","parasitose intestinal leve."]'::jsonb, 0, 'Diarreia persistente é a que dura 14 dias ou mais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-357', 'enf', null, 'Em lactentes menores de 2 meses, a presença de febre:', '["é sinal de alerta e exige avaliação imediata, pela possibilidade de infecção bacteriana grave.","é esperada e não exige avaliação.","deve ser tratada apenas com banho morno em casa.","indica apenas excesso de roupas.","só deve ser investigada após 3 dias."]'::jsonb, 0, 'Nessa faixa etária, os sinais de infecção grave são pouco específicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-358', 'enf', null, 'A bronquiolite viral aguda, frequente em lactentes, tem como principal agente etiológico o:', '["vírus sincicial respiratório (VSR).","vírus da hepatite A.","Streptococcus pyogenes.","vírus da varicela.","Mycobacterium tuberculosis."]'::jsonb, 0, 'O tratamento é de suporte: hidratação, desobstrução nasal e oxigênio quando necessário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-359', 'enf', null, 'A crise febril simples na infância caracteriza-se por:', '["ocorrer entre 6 meses e 5 anos, ser generalizada, durar menos de 15 minutos e não se repetir em 24 horas.","ocorrer em adultos com febre baixa.","durar mais de 30 minutos e ser focal.","deixar sequelas neurológicas em todos os casos.","ocorrer apenas sem febre."]'::jsonb, 0, 'As crises complexas (focais, prolongadas ou repetidas) exigem investigação adicional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-360', 'enf', null, 'Na desnutrição grave, a forma caracterizada por edema, alterações de cabelo e pele e hipoalbuminemia é denominada:', '["kwashiorkor.","marasmo.","obesidade sarcopênica.","baixa estatura familiar.","raquitismo."]'::jsonb, 0, 'O marasmo se caracteriza por emagrecimento acentuado, sem edema.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-361', 'enf', null, 'São sinais que levantam suspeita de maus-tratos na criança:', '["lesões em diferentes estágios de cicatrização, em locais pouco comuns para acidentes, e relato incompatível com o tipo de lesão.","joelhos ralados em criança que começou a andar.","hematoma isolado na testa após queda relatada e compatível.","picadas de inseto nas pernas.","febre com tosse."]'::jsonb, 0, 'A suspeita deve ser notificada e comunicada ao Conselho Tutelar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-362', 'enf', null, 'Na avaliação da maturação sexual do adolescente, utiliza-se:', '["os estágios de Tanner.","a escala de Glasgow.","o índice de Apgar.","a escala de Braden.","o método de Capurro."]'::jsonb, 0, 'Os estágios de Tanner avaliam mamas e pelos pubianos (meninas) e genitais e pelos pubianos (meninos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-363', 'enf', null, 'Quanto ao peso ao nascer, considera-se recém-nascido de muito baixo peso aquele com peso:', '["inferior a 1.500 g.","inferior a 2.500 g.","inferior a 1.000 g.","entre 2.500 e 4.000 g.","superior a 4.000 g."]'::jsonb, 0, 'Baixo peso: < 2.500 g; muito baixo peso: < 1.500 g; extremo baixo peso: < 1.000 g.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-364', 'enf', null, 'O recém-nascido cujo peso ao nascer está abaixo do percentil 10 para a idade gestacional é classificado como:', '["pequeno para a idade gestacional (PIG).","adequado para a idade gestacional (AIG).","grande para a idade gestacional (GIG).","pós-termo.","prematuro extremo, obrigatoriamente."]'::jsonb, 0, 'GIG: acima do percentil 90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-365', 'enf', null, 'O método de Capurro é utilizado no recém-nascido para:', '["estimar a idade gestacional com base em características físicas (e neurológicas, em algumas versões).","avaliar a vitalidade ao nascer.","classificar o risco de queda.","avaliar a dor neonatal.","medir o perímetro cefálico."]'::jsonb, 0, 'O New Ballard é outro método utilizado, especialmente em prematuros.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-366', 'enf', null, 'A síndrome do desconforto respiratório do recém-nascido prematuro (doença da membrana hialina) é causada principalmente por:', '["deficiência de surfactante pulmonar.","aspiração de mecônio.","infecção por vírus sincicial respiratório.","excesso de líquido pulmonar em RN a termo.","cardiopatia congênita."]'::jsonb, 0, 'Corticoide antenatal e surfactante exógeno são medidas de prevenção e tratamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-367', 'enf', null, 'A taquipneia transitória do recém-nascido está associada principalmente a:', '["retardo na absorção do líquido pulmonar, sendo mais comum após cesariana eletiva sem trabalho de parto.","deficiência de surfactante em prematuros extremos.","infecção bacteriana grave.","obstrução nasal congênita.","hipoglicemia."]'::jsonb, 0, 'Costuma resolver-se em 24 a 72 horas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-368', 'enf', null, 'Os mecanismos de perda de calor do recém-nascido incluem, entre outros, a perda por evaporação, que ocorre quando:', '["a pele permanece molhada após o nascimento ou após o banho.","o RN é colocado sobre superfície fria.","há correntes de ar no ambiente.","o RN fica próximo a paredes frias, sem contato.","o RN é envolvido em campo aquecido."]'::jsonb, 0, 'Condução: contato com superfícies frias; convecção: correntes de ar; radiação: proximidade de superfícies frias sem contato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-369', 'enf', null, 'A enterocolite necrosante, complicação grave em prematuros, tem como fator de proteção:', '["o aleitamento com leite humano.","o jejum prolongado em todos os prematuros.","a fórmula infantil exclusiva.","o uso rotineiro de antibióticos.","a oferta de água."]'::jsonb, 0, 'Distensão abdominal, resíduo gástrico bilioso e sangue nas fezes são sinais de alerta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-370', 'enf', null, 'A retinopatia da prematuridade está associada, entre outros fatores, a:', '["baixa idade gestacional, baixo peso ao nascer e uso de oxigênio, exigindo exame oftalmológico de rastreamento.","excesso de luz solar.","alimentação com leite materno.","uso de colírio de rotina.","nascimento a termo."]'::jsonb, 0, 'O controle da saturação de oxigênio dentro das metas reduz o risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-371', 'enf', null, 'A sepse neonatal precoce é aquela que se manifesta:', '["nas primeiras 48 a 72 horas de vida, geralmente associada a fatores maternos e do parto.","após 30 dias de vida.","apenas em recém-nascidos a termo.","somente após a alta hospitalar.","exclusivamente por vírus."]'::jsonb, 0, 'A sepse tardia costuma relacionar-se a germes do ambiente hospitalar e a procedimentos invasivos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-372', 'enf', null, 'O Método Canguru é organizado em três etapas. A segunda etapa ocorre:', '["na Unidade de Cuidados Intermediários Neonatal Canguru, com a mãe acompanhando o recém-nascido de forma contínua.","no pré-natal de alto risco.","no domicílio, após a alta.","na sala de parto, nos primeiros minutos.","na UTI pediátrica."]'::jsonb, 0, 'A primeira etapa ocorre na UTI neonatal e a terceira, após a alta, com acompanhamento ambulatorial.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-373', 'enf', null, 'No teste do coraçãozinho (oximetria de pulso), o resultado é considerado normal quando:', '["a saturação for igual ou superior a 95% no membro superior direito e em um membro inferior, com diferença inferior a 3% entre eles.","a saturação for de 85% em ambos os membros.","a diferença entre os membros for de 10%.","a saturação no membro inferior for maior que 100%.","o teste for realizado com 2 horas de vida."]'::jsonb, 0, 'Resultado alterado exige repetição ou encaminhamento para ecocardiograma, conforme o protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-374', 'enf', null, 'No Programa Nacional de Triagem Neonatal (teste do pezinho), estão entre as doenças triadas:', '["fenilcetonúria, hipotireoidismo congênito, doença falciforme e outras hemoglobinopatias, fibrose cística, hiperplasia adrenal congênita e deficiência de biotinidase.","diabetes tipo 2 e hipertensão.","surdez e catarata.","cardiopatias congênitas críticas.","anquiloglossia."]'::jsonb, 0, 'Surdez, catarata e cardiopatias são rastreadas por outros testes (orelhinha, olhinho e coraçãozinho).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-375', 'enf', null, 'Na criança com doença falciforme, entre as medidas de prevenção de complicações, destaca-se:', '["a profilaxia com penicilina e a vacinação com imunobiológicos especiais, pelo maior risco de infecções.","a restrição total de líquidos.","a suspensão das vacinas do calendário.","a exposição ao frio para reduzir as crises.","o uso diário de ferro em altas doses, sem avaliação."]'::jsonb, 0, 'A hidratação adequada e o reconhecimento precoce de febre também são fundamentais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-376', 'enf', null, 'Na criança com hipotireoidismo congênito identificado no teste do pezinho, o início precoce do tratamento é fundamental para:', '["prevenir a deficiência intelectual e alterações do crescimento.","evitar a perda auditiva.","prevenir a catarata congênita.","evitar a icterícia.","prevenir a doença falciforme."]'::jsonb, 0, 'O tratamento é feito com levotiroxina, com acompanhamento especializado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-377', 'enf', null, 'Um episódio hipotônico-hiporresponsivo após a vacinação, caracterizado por diminuição do tônus muscular, palidez e redução da resposta a estímulos, está mais associado às vacinas que contêm o componente:', '["pertussis (coqueluche), como a pentavalente e a DTP.","BCG.","rotavírus.","febre amarela.","hepatite B isolada."]'::jsonb, 0, 'É evento geralmente benigno e transitório, mas deve ser notificado e avaliado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-378', 'enf', null, 'Para pessoas com imunodeficiência grave, de modo geral, são contraindicadas as vacinas:', '["de microrganismos vivos atenuados, como tríplice viral, varicela, febre amarela e BCG.","inativadas, como a influenza.","de toxoides, como a dT.","recombinantes, como a hepatite B.","conjugadas, como a pneumocócica."]'::jsonb, 0, 'Os Centros de Referência para Imunobiológicos Especiais (CRIE) orientam esquemas específicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-379', 'enf', null, 'Os Centros de Referência para Imunobiológicos Especiais (CRIE) têm como finalidade:', '["atender pessoas com condições clínicas especiais que necessitam de imunobiológicos não disponíveis na rotina ou de esquemas diferenciados.","substituir as salas de vacina da Atenção Básica.","vacinar apenas viajantes internacionais.","produzir vacinas.","fiscalizar a rede de frio."]'::jsonb, 0, 'Exemplos: pessoas com HIV, transplantados, imunodeprimidos e prematuros extremos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-380', 'enf', null, 'No esquema de profilaxia da raiva humana pós-exposição com vacina por via intramuscular, conforme o Ministério da Saúde (2022), são aplicadas:', '["4 doses, nos dias 0, 3, 7 e 14.","1 dose única.","5 doses, nos dias 0, 3, 7, 14 e 28, em qualquer situação.","2 doses com intervalo de 1 ano.","3 doses, nos dias 0, 30 e 60."]'::jsonb, 0, 'Conforme o tipo de exposição, pode haver indicação também de soro ou imunoglobulina antirrábica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-381', 'enf', null, 'Na profilaxia do tétano em ferimento de alto risco (profundo e sujo), em pessoa com esquema vacinal completo e última dose há mais de 5 anos, recomenda-se:', '["uma dose de reforço da vacina, além da limpeza adequada do ferimento.","nenhuma conduta, pois o esquema está completo.","reiniciar todo o esquema vacinal.","apenas antibiótico.","apenas soro antitetânico, sem vacina."]'::jsonb, 0, 'Em pessoas com esquema incompleto ou desconhecido, pode haver indicação de imunização passiva associada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-382', 'enf', null, 'São exemplos de vacinas sensíveis ao congelamento, que perdem a potência se expostas a temperaturas negativas:', '["pentavalente, hepatite B, HPV e influenza.","todas as vacinas, sem exceção, toleram o congelamento.","apenas as vacinas orais.","somente a BCG.","nenhuma vacina do calendário."]'::jsonb, 0, 'Por isso, a temperatura das câmaras deve ser mantida entre +2 °C e +8 °C (ideal +5 °C).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-383', 'enf', null, 'Segundo o calendário do PNI, a vacina febre amarela é indicada:', '["aos 9 meses, com reforço aos 4 anos; pessoas de 5 a 59 anos sem comprovação vacinal recebem dose única.","ao nascer, em dose única.","apenas para maiores de 60 anos.","anualmente, para toda a população.","somente para viajantes internacionais."]'::jsonb, 0, 'Pessoas acima de 60 anos devem ter a indicação avaliada individualmente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-384', 'enf', null, 'No acompanhamento de um recém-nascido com icterícia, a progressão crânio-caudal da coloração amarelada, avaliada pelas zonas de Kramer, permite:', '["estimar clinicamente a intensidade da icterícia, sem dispensar a dosagem de bilirrubina quando indicada.","diagnosticar a causa da icterícia.","substituir a fototerapia.","medir a bilirrubina com exatidão.","avaliar a idade gestacional."]'::jsonb, 0, 'Quanto mais distal a icterícia (até mãos e pés), maior tende a ser o nível de bilirrubina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-385', 'enf', null, 'O kernicterus, complicação grave da hiperbilirrubinemia neonatal, corresponde a:', '["deposição de bilirrubina indireta em núcleos do sistema nervoso central, podendo causar sequelas neurológicas permanentes.","infecção do coto umbilical.","anemia por deficiência de ferro.","hipoglicemia neonatal.","obstrução intestinal."]'::jsonb, 0, 'O tratamento oportuno com fototerapia ou exsanguineotransfusão previne o kernicterus.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-386', 'enf', null, 'Para o recém-nascido prematuro internado na UTI neonatal, o alimento de escolha é:', '["o leite humano, preferencialmente da própria mãe, ou o leite humano pasteurizado do Banco de Leite.","a fórmula infantil comum, como primeira opção.","o leite de vaca integral diluído.","o soro glicosado por via oral como único alimento.","o chá de camomila."]'::jsonb, 0, 'O leite humano protege contra infecções e enterocolite necrosante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-387', 'enf', null, 'Para uma criança de 15 kg, a necessidade hídrica diária de manutenção calculada pela regra de Holliday-Segar é de:', '["1.250 mL/dia.","1.500 mL/dia.","750 mL/dia.","2.000 mL/dia.","1.000 mL/dia."]'::jsonb, 0, '100 mL/kg para os primeiros 10 kg (1.000 mL) + 50 mL/kg para os 5 kg seguintes (250 mL) = 1.250 mL/dia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-388', 'enf', null, 'Foi prescrito paracetamol 15 mg/kg para uma criança de 12 kg. A apresentação disponível é solução de 200 mg/mL. O volume a ser administrado é de:', '["0,9 mL.","1,8 mL.","0,6 mL.","9 mL.","0,18 mL."]'::jsonb, 0, '15 mg × 12 kg = 180 mg; 200 mg — 1 mL; 180 mg — x → x = 0,9 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-389', 'enf', null, 'Durante a consulta de puericultura na Atenção Primária, o enfermeiro orienta os responsáveis sobre a alimentação na infância. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-390', 'enf', null, 'No Programa Saúde na Escola (PSE), a atuação da equipe de saúde nas escolas tem como objetivo:', '["contribuir para a formação integral dos estudantes por meio de ações de promoção, prevenção e atenção à saúde, articuladas com a educação.","substituir o atendimento nas Unidades Básicas de Saúde.","realizar apenas vacinação.","fiscalizar os professores.","aplicar avaliações escolares."]'::jsonb, 0, 'O PSE é uma política intersetorial entre os Ministérios da Saúde e da Educação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-391', 'enf', null, 'Na consulta de enfermagem ao adolescente, uma conduta adequada é:', '["garantir privacidade e confidencialidade, oferecer espaço para o adolescente ser atendido sozinho e explicar os limites do sigilo.","exigir a presença dos pais para qualquer orientação.","comunicar aos pais tudo o que for conversado, sem exceção.","evitar falar sobre sexualidade.","condicionar o atendimento à apresentação de documento assinado pelos pais."]'::jsonb, 0, 'O sigilo pode ser quebrado em situações de risco à vida ou previstas em lei.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-392', 'enf', null, 'Na avaliação do desenvolvimento infantil com a Caderneta da Criança, a ausência de um marco esperado para a faixa etária indica que o enfermeiro deve:', '["orientar a família, estimular a criança e reavaliar em menor intervalo ou encaminhar para avaliação, conforme a classificação.","ignorar, pois cada criança tem seu tempo.","diagnosticar transtorno do espectro autista imediatamente.","suspender o acompanhamento.","prescrever medicamentos para o desenvolvimento."]'::jsonb, 0, 'A vigilância do desenvolvimento permite identificar e intervir precocemente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-393', 'enf', null, 'No acompanhamento de uma criança com diarreia sem desidratação (Plano A), as orientações à família incluem:', '["oferecer mais líquidos que o habitual, inclusive SRO após cada evacuação, manter a alimentação e reconhecer os sinais de perigo para retorno.","suspender a alimentação até cessar a diarreia.","usar antidiarreico de rotina.","oferecer refrigerante como principal líquido.","suspender o aleitamento materno."]'::jsonb, 0, 'O zinco também é recomendado na diarreia aguda em crianças, conforme protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-394', 'enf', null, 'A suplementação de zinco na criança com diarreia aguda tem como benefício:', '["reduzir a duração e a gravidade do episódio e a ocorrência de novos episódios.","curar a desidratação grave sem hidratação.","substituir o soro de reidratação oral.","eliminar os parasitas intestinais.","aumentar a frequência das evacuações."]'::jsonb, 0, 'É associada à reidratação oral e à manutenção da alimentação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-395', 'enf', null, 'Na criança com asma, a orientação sobre o uso do dispositivo inalatório pressurizado ("bombinha") deve incluir:', '["o uso de espaçador, com máscara facial em crianças pequenas, para melhorar a deposição do medicamento.","o uso sem espaçador em todas as idades.","o uso apenas durante as crises, inclusive dos medicamentos de manutenção.","a aplicação do jato diretamente no nariz.","a suspensão do corticoide inalatório quando a criança estiver bem, sem orientação."]'::jsonb, 0, 'Os medicamentos de manutenção devem ser usados regularmente, conforme prescrição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-396', 'enf', null, 'Na consulta de enfermagem à criança com sobrepeso, a abordagem adequada inclui:', '["orientar a família sobre alimentação adequada e saudável, redução de ultraprocessados e bebidas açucaradas, atividade física e limitação do tempo de telas.","prescrever dieta restritiva de 800 calorias.","orientar o jejum prolongado.","recomendar medicamentos para emagrecer.","culpar a criança pelo excesso de peso."]'::jsonb, 0, 'A abordagem deve envolver toda a família e respeitar o contexto social.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-397', 'enf', null, 'A vacina influenza é recomendada anualmente para crianças na faixa etária de:', '["6 meses a menores de 6 anos, entre outros grupos prioritários.","recém-nascidos a partir do primeiro dia de vida.","apenas crianças com mais de 10 anos.","somente adolescentes.","crianças de qualquer idade, exceto menores de 5 anos."]'::jsonb, 0, 'Crianças vacinadas pela primeira vez, até 8 anos, recebem duas doses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-398', 'enf', null, 'A Rede de Frio recomenda que a temperatura ideal das câmaras refrigeradas de conservação de vacinas seja de:', '["+5 °C, dentro da faixa de +2 °C a +8 °C.","0 °C.","-20 °C para todas as vacinas.","+10 °C.","+15 °C."]'::jsonb, 0, 'O monitoramento contínuo e os registros diários são obrigatórios.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-399', 'enf', null, 'No acompanhamento de lactente com refluxo gastroesofágico fisiológico, a orientação adequada é:', '["manter o aleitamento, evitar mamadas excessivas, manter a criança em posição elevada após as mamadas e tranquilizar a família.","suspender o aleitamento materno.","colocar o bebê para dormir em decúbito ventral.","iniciar medicamentos em todos os casos.","oferecer chás para melhorar a digestão."]'::jsonb, 0, 'O refluxo fisiológico tende a melhorar com o crescimento; sinais de alerta exigem avaliação médica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-400', 'enf', null, 'O recém-nascido que apresenta, nas primeiras horas de vida, vômitos esverdeados (biliosos) deve ser:', '["avaliado imediatamente, pela suspeita de obstrução intestinal.","mantido em observação domiciliar.","alimentado com maior volume.","tratado apenas com mudança de posição.","considerado normal."]'::jsonb, 0, 'Vômito bilioso no período neonatal é sinal de alarme.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-401', 'enf', null, 'No ambiente da UTI neonatal, uma estratégia de cuidado desenvolvimental que reduz o estresse do prematuro é:', '["reduzir ruídos e luminosidade, agrupar os procedimentos e favorecer o posicionamento em flexão e o contato com os pais.","manter a luz acesa 24 horas para facilitar a observação.","manipular o recém-nascido o máximo possível.","restringir a presença dos pais.","deixar alarmes soando continuamente."]'::jsonb, 0, 'O cuidado centrado na família é princípio da atenção neonatal humanizada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-402', 'enf', null, 'A escala utilizada para avaliação da dor em recém-nascidos, baseada em expressão facial, choro, respiração, movimentos e estado de alerta, é a:', '["NIPS (Neonatal Infant Pain Scale).","escala numérica de 0 a 10.","escala de Morse.","escala de Braden Q.","escala de Glasgow."]'::jsonb, 0, 'Medidas não farmacológicas, como sucção não nutritiva, sacarose e contato pele a pele, reduzem a dor em procedimentos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-403', 'enf', null, 'Na consulta da criança vítima de acidente doméstico por queimadura com líquido quente, além do cuidado com a lesão, o enfermeiro deve:', '["avaliar o contexto, orientar a prevenção de acidentes e considerar a possibilidade de negligência ou maus-tratos, conforme os achados.","registrar apenas a lesão, sem avaliar o contexto.","liberar a criança sem orientação.","aplicar pasta de dente na lesão.","culpabilizar a família publicamente."]'::jsonb, 0, 'A identificação de padrões suspeitos deve levar à notificação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-404', 'enf', null, 'Na consulta de puericultura, o enfermeiro identifica uma criança de 18 meses com caderneta de vacinação incompleta. A conduta correta é:', '["atualizar a situação vacinal, aplicando as vacinas em atraso indicadas para a idade e agendando as próximas, sem reiniciar esquemas.","aguardar o próximo ano para vacinar.","reiniciar todos os esquemas desde o início.","aplicar apenas as vacinas orais.","encaminhar para o CRIE em todos os casos."]'::jsonb, 0, 'No PNI, as doses já aplicadas são consideradas válidas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-405', 'enf', null, 'O PNI recomenda que a vacina BCG seja aplicada:', '["o mais precocemente possível, de preferência na maternidade, em recém-nascidos com peso igual ou superior a 2.000 g.","apenas aos 6 meses.","em todos os adultos, a cada 10 anos.","somente em crianças com tuberculose.","por via oral."]'::jsonb, 0, 'Crianças não vacinadas podem receber a BCG até 4 anos, 11 meses e 29 dias.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-406', 'enf', null, 'Na ventilação mecânica, a pressão positiva expiratória final (PEEP) tem como principal função:', '["manter os alvéolos abertos ao final da expiração, melhorando a oxigenação.","aumentar a frequência respiratória.","reduzir a fração inspirada de oxigênio a zero.","eliminar a necessidade de sedação.","promover a extubação imediata."]'::jsonb, 0, 'Valores elevados de PEEP podem reduzir o retorno venoso e causar hipotensão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-407', 'enf', null, 'O processo de desmame da ventilação mecânica envolve a avaliação da prontidão do paciente. Durante o Teste de Respiração Espontânea (TRE), a conduta é:', '["conectar o paciente a um tubo T ou ajustar o ventilador para baixo suporte pressórico, por 30 a 120 minutos, monitorando sinais de falha.","hiperventilar o paciente com FiO2 a 100% por 30 minutos e extubá-lo imediatamente.","aumentar a sedação para que o ventilador possa ser desligado com segurança.","realizar a extubação imediata sem monitorar sinais de fadiga respiratória.","extubar assim que o paciente acordar, sem testes prévios."]'::jsonb, 0, 'Sinais de falha incluem taquipneia, taquicardia, queda de saturação, agitação e uso de musculatura acessória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-408', 'enf', null, 'Após a extubação, o enfermeiro deve observar atentamente a presença de:', '["estridor laríngeo, desconforto respiratório e queda da saturação.","aumento do apetite.","melhora imediata da fala, sempre.","diurese aumentada.","bradipneia como sinal de sucesso."]'::jsonb, 0, 'O estridor pode indicar edema de glote; a cabeceira deve permanecer elevada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-409', 'enf', null, 'A pressão recomendada para o balonete (cuff) do tubo endotraqueal, para prevenir tanto a microaspiração quanto a isquemia da mucosa traqueal, é de:', '["20 a 30 cmH2O.","abaixo de 10 cmH2O.","50 a 60 cmH2O.","100 cmH2O.","não é necessário medir a pressão."]'::jsonb, 0, 'A medida deve ser feita com cuffômetro, periodicamente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-410', 'enf', null, 'Os valores de referência da gasometria arterial considerados normais são:', '["pH 7,35–7,45; PaCO2 35–45 mmHg; HCO3- 22–26 mEq/L.","pH 7,00–7,20; PaCO2 60–80 mmHg; HCO3- 10–15 mEq/L.","pH 7,50–7,60; PaCO2 20–25 mmHg; HCO3- 30–35 mEq/L.","pH 6,8–7,0; PaCO2 10–20 mmHg; HCO3- 40–50 mEq/L.","pH 8,0; PaCO2 45–55 mmHg; HCO3- 20 mEq/L."]'::jsonb, 0, 'A PaO2 normal em ar ambiente é de cerca de 80 a 100 mmHg.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-411', 'enf', null, 'Gasometria arterial com pH 7,52, PaCO2 28 mmHg e HCO3- 24 mEq/L, em paciente ansioso e taquipneico, indica:', '["alcalose respiratória.","acidose respiratória.","acidose metabólica.","alcalose metabólica.","gasometria normal."]'::jsonb, 0, 'pH elevado com PaCO2 baixa e bicarbonato normal: alcalose respiratória por hiperventilação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-412', 'enf', null, 'Na monitorização da pressão arterial invasiva, o transdutor deve ser nivelado e zerado no eixo flebostático, que corresponde:', '["ao 4º espaço intercostal, na linha axilar média.","ao 2º espaço intercostal, na linha hemiclavicular.","à altura do umbigo.","à altura do joelho.","ao nível do ombro."]'::jsonb, 0, 'O desnivelamento do transdutor gera leituras falsamente altas ou baixas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-413', 'enf', null, 'Sobre os cuidados de enfermagem ao paciente em nutrição parenteral, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-414', 'enf', null, 'Na unidade de terapia intensiva, a interrupção diária da sedação (despertar diário) tem como benefícios:', '["reduzir o tempo de ventilação mecânica e de internação, permitindo avaliar o nível de consciência.","aumentar a necessidade de sedação nos dias seguintes.","prolongar a ventilação mecânica.","dispensar a avaliação neurológica.","aumentar a incidência de pneumonia."]'::jsonb, 0, 'Faz parte do bundle de prevenção da pneumonia associada à ventilação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-415', 'enf', null, 'Na manutenção do potencial doador de órgãos após o diagnóstico de morte encefálica, o enfermeiro deve estar atento a alterações como:', '["hipotensão, hipotermia e poliúria por diabetes insípido, que devem ser corrigidas para preservar os órgãos.","hipertensão persistente sem necessidade de intervenção.","febre alta como sinal esperado.","aumento do nível de consciência.","retorno da respiração espontânea."]'::jsonb, 0, 'A manutenção hemodinâmica adequada é decisiva para a viabilidade dos órgãos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-416', 'enf', null, 'No paciente em diálise peritoneal, o sinal mais característico de peritonite é:', '["efluente (líquido drenado) turvo, acompanhado de dor abdominal.","efluente claro e transparente.","aumento da diurese.","ganho de apetite.","hipertensão isolada."]'::jsonb, 0, 'A técnica asséptica na troca das bolsas é a principal medida de prevenção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-417', 'enf', null, 'Durante a sessão de hemodiálise, a complicação mais frequente é:', '["hipotensão arterial.","hipertensão maligna.","hiperglicemia grave.","bradicardia extrema.","febre alta."]'::jsonb, 0, 'Cãibras, náuseas e cefaleia também podem ocorrer.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-418', 'enf', null, 'Na insuficiência renal aguda com oligúria, um distúrbio eletrolítico que exige monitorização rigorosa pelo risco de arritmias é a:', '["hipercalemia.","hipocalcemia isolada sem importância.","hiponatremia leve.","hipofosfatemia.","hipermagnesemia sem risco."]'::jsonb, 0, 'O ECG pode mostrar ondas T apiculadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-419', 'enf', null, 'No paciente com cirrose hepática e encefalopatia hepática, o medicamento frequentemente utilizado para reduzir a absorção de amônia é:', '["lactulose.","furosemida.","omeprazol.","insulina.","heparina."]'::jsonb, 0, 'O objetivo é obter 2 a 3 evacuações pastosas por dia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-420', 'enf', null, 'No pós-operatório, o paciente refere ter sentido "algo se abrir" na incisão após tossir, e há saída de alças intestinais. A conduta imediata do enfermeiro é:', '["cobrir as vísceras com compressa estéril umedecida em soro fisiológico, manter o paciente em repouso com os joelhos fletidos e comunicar imediatamente o cirurgião.","reintroduzir as alças intestinais.","aplicar compressa seca e pressionar.","estimular a deambulação.","oferecer dieta via oral."]'::jsonb, 0, 'A evisceração é emergência cirúrgica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-421', 'enf', null, 'Os tempos cirúrgicos fundamentais são, na ordem:', '["diérese, hemostasia, exérese e síntese.","síntese, exérese, hemostasia e diérese.","hemostasia, síntese, diérese e exérese.","exérese, diérese, síntese e hemostasia.","diérese, síntese, hemostasia e exérese."]'::jsonb, 0, 'Diérese: abertura dos tecidos; hemostasia: controle do sangramento; exérese: o procedimento principal; síntese: fechamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-422', 'enf', null, 'Quanto ao potencial de contaminação, uma apendicectomia com apêndice perfurado e presença de pus é classificada como cirurgia:', '["infectada.","limpa.","potencialmente contaminada.","contaminada, sem infecção.","eletiva limpa."]'::jsonb, 0, 'Cirurgias limpas não penetram tratos colonizados; as infectadas envolvem tecido com infecção ou pus.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-423', 'enf', null, 'Após raquianestesia, o paciente refere cefaleia intensa que piora ao sentar e melhora ao deitar. Essa complicação é chamada de:', '["cefaleia pós-punção dural.","hipertermia maligna.","anafilaxia.","intoxicação por anestésico local.","enxaqueca crônica."]'::jsonb, 0, 'As medidas incluem repouso, hidratação, analgesia e, em casos refratários, tampão sanguíneo peridural.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-424', 'enf', null, 'A hipertermia maligna, complicação rara e grave da anestesia geral com anestésicos inalatórios e succinilcolina, é tratada com:', '["dantrolene sódico, além da suspensão dos agentes desencadeantes e medidas de resfriamento.","naloxona.","atropina.","flumazenil.","protamina."]'::jsonb, 0, 'Os sinais incluem aumento do CO2 expirado, rigidez muscular, taquicardia e hipertermia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-425', 'enf', null, 'Na antissepsia cirúrgica das mãos com clorexidina degermante, a escovação ou fricção deve durar, em geral, de:', '["3 a 5 minutos para a primeira cirurgia.","10 segundos.","15 minutos.","30 segundos.","1 hora."]'::jsonb, 0, 'As preparações alcoólicas com ação residual também podem ser usadas conforme o protocolo institucional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-426', 'enf', null, 'Entre as medidas de prevenção da infecção do sítio cirúrgico, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-427', 'enf', null, 'Segundo a RDC ANVISA nº 15/2012, a CME classe II é aquela que realiza o processamento de produtos para saúde:', '["não críticos, semicríticos e críticos de conformação complexa e não complexa, passíveis de processamento.","apenas não críticos.","apenas de conformação não complexa.","exclusivamente de uso único.","apenas de odontologia."]'::jsonb, 0, 'A CME classe I processa produtos de conformação não complexa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-428', 'enf', null, 'Na classificação dos indicadores químicos de esterilização, o indicador que reage a todos os parâmetros críticos do ciclo e cujo desempenho é correlacionado ao do indicador biológico é o:', '["indicador integrador (classe 5).","indicador de processo (classe 1).","teste de Bowie-Dick (classe 2).","indicador de parâmetro único (classe 3).","fita adesiva zebrada."]'::jsonb, 0, 'A classe 6 corresponde aos emuladores, específicos para determinados ciclos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-429', 'enf', null, 'A lavadora termodesinfectora, utilizada na CME, realiza:', '["limpeza automatizada e desinfecção por ação térmica.","esterilização por óxido de etileno.","esterilização por plasma.","apenas a secagem dos materiais.","o armazenamento dos materiais estéreis."]'::jsonb, 0, 'A termodesinfecção reduz a manipulação de materiais contaminados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-430', 'enf', null, 'Segundo a regulamentação sanitária brasileira (RE ANVISA nº 2.605/2006), alguns produtos para saúde enquadrados como de uso único:', '["têm o reprocessamento proibido, conforme lista definida pela ANVISA.","podem ser reprocessados livremente.","devem ser reprocessados obrigatoriamente.","só podem ser usados após três reprocessamentos.","dispensam qualquer controle."]'::jsonb, 0, 'O reprocessamento indevido expõe o paciente a riscos de infecção e falhas do produto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-431', 'enf', null, 'No controle de microrganismos multirresistentes em unidade de internação, uma medida recomendada é:', '["precaução de contato, com possibilidade de coorte de pacientes colonizados ou infectados pelo mesmo microrganismo.","precaução para aerossóis em todos os casos.","suspender a higiene das mãos quando há uso de luvas.","compartilhar estetoscópios entre pacientes.","remover os pacientes da unidade sem comunicação à CCIH."]'::jsonb, 0, 'A CCIH orienta a vigilância e as medidas de controle.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-432', 'enf', null, 'Na avaliação e no tratamento de feridas, o acrônimo TIME orienta a preparação do leito da ferida e se refere a:', '["Tecido, Infecção/Inflamação, Umidade e Bordas (Edge).","Tempo, Intensidade, Medida e Extensão.","Temperatura, Isquemia, Mobilidade e Exsudato.","Tamanho, Inflamação, Medicação e Edema.","Tratamento, Internação, Monitorização e Evolução."]'::jsonb, 0, 'Cada elemento orienta intervenções, como desbridamento, controle de carga bacteriana e manejo do exsudato.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-433', 'enf', null, 'Associe os tipos de desbridamento aos seus exemplos.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-434', 'enf', null, 'Na escala de Braden, um paciente com escore total de 11 pontos é classificado com risco:', '["alto para lesão por pressão.","ausente.","leve.","moderado, exclusivamente acima de 15 pontos.","não é possível classificar com esse escore."]'::jsonb, 0, 'Faixas usuais: 15–18 risco leve; 13–14 moderado; 10–12 alto; ≤ 9 muito alto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-435', 'enf', null, 'A lesão por pressão relacionada a dispositivo médico é aquela que:', '["resulta do uso de dispositivos criados e aplicados para fins diagnósticos ou terapêuticos, geralmente com o formato do dispositivo.","ocorre apenas no sacro.","não pode ser classificada.","surge somente em pacientes ambulatoriais.","é causada exclusivamente pela umidade."]'::jsonb, 0, 'Exemplos: lesões por cateter nasal, máscara de VNI, sonda e tubo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-436', 'enf', null, 'A dermatite associada à incontinência diferencia-se da lesão por pressão porque:', '["decorre da exposição da pele à urina ou às fezes, com eritema difuso e bordas mal definidas, e não necessariamente sobre proeminência óssea.","sempre ocorre sobre proeminências ósseas.","apresenta necrose em todos os casos.","é causada apenas por pressão e cisalhamento.","não exige cuidados preventivos."]'::jsonb, 0, 'A prevenção inclui limpeza suave, hidratação e uso de protetores cutâneos de barreira.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-437', 'enf', null, 'Na ferida de queimadura de segundo grau, um tratamento tópico tradicionalmente utilizado, com ação antimicrobiana, é a:', '["sulfadiazina de prata 1%.","pasta de dente.","manteiga.","álcool 70%.","água oxigenada pura."]'::jsonb, 0, 'Coberturas com prata e outras tecnologias também podem ser utilizadas, conforme o protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-438', 'enf', null, 'O índice tornozelo-braço (ITB) inferior a 0,9 sugere:', '["doença arterial obstrutiva periférica.","insuficiência venosa sem acometimento arterial.","circulação arterial normal.","trombose venosa profunda aguda.","linfedema."]'::jsonb, 0, 'Valores muito baixos indicam isquemia grave e contraindicam terapia compressiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-439', 'enf', null, 'No paciente oncológico em quimioterapia, a neutropenia febril:', '["é emergência oncológica, exigindo coleta de culturas e início precoce de antibiótico.","é esperada e não exige avaliação.","deve ser tratada apenas com antitérmico em casa.","contraindica a internação.","ocorre apenas em crianças."]'::jsonb, 0, 'Medidas de proteção, como higiene das mãos e cuidados com alimentos, reduzem o risco de infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-440', 'enf', null, 'Durante a transfusão de concentrado de hemácias, o paciente apresenta febre, calafrios, dor lombar, hipotensão e urina avermelhada. A principal hipótese é:', '["reação hemolítica aguda, geralmente por incompatibilidade ABO.","reação febril não hemolítica leve.","reação alérgica leve.","sobrecarga circulatória isolada.","hipoglicemia."]'::jsonb, 0, 'Conduta: interromper a transfusão, manter o acesso com SF, comunicar o médico e o serviço de hemoterapia e notificar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-441', 'enf', null, 'Na maioria dos pacientes críticos em uso de insulina, a meta glicêmica recomendada é de:', '["140 a 180 mg/dL.","70 a 90 mg/dL.","200 a 250 mg/dL.","40 a 60 mg/dL.","acima de 300 mg/dL."]'::jsonb, 0, 'O controle glicêmico muito rigoroso aumenta o risco de hipoglicemia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-442', 'enf', null, 'A inserção do cateter central de inserção periférica (PICC) pode ser realizada pelo enfermeiro:', '["desde que devidamente qualificado e capacitado, conforme regulamentação do COFEN.","sem capacitação, em qualquer situação.","apenas sob supervisão do técnico de enfermagem.","somente em adultos, sem treinamento.","não pode ser realizada por enfermeiros."]'::jsonb, 0, 'Resolução COFEN nº 258/2001; a confirmação da posição da ponta é feita por imagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-443', 'enf', null, 'Na prevenção do tromboembolismo venoso no paciente cirúrgico, são medidas recomendadas:', '["deambulação precoce, profilaxia farmacológica e/ou mecânica conforme a avaliação de risco.","repouso absoluto prolongado.","restrição de líquidos.","uso de roupas apertadas nas pernas.","massagem vigorosa nas panturrilhas."]'::jsonb, 0, 'A massagem em membro com suspeita de trombose é contraindicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-444', 'enf', null, 'No paciente em uso de dreno de tórax com sistema de selo d''água, a presença de borbulhamento contínuo no frasco pode indicar:', '["fuga de ar do pulmão ou vazamento no sistema, devendo ser investigada.","funcionamento normal esperado em todos os casos.","obstrução completa do dreno.","reexpansão pulmonar completa.","infecção do sítio de inserção."]'::jsonb, 0, 'O borbulhamento intermitente na expiração pode ocorrer em pneumotórax em resolução.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-445', 'enf', null, 'No paciente com dreno de tórax em selo d''água, o cuidado essencial no manejo do dispositivo é:', '["manter o frasco de drenagem sempre abaixo do nível do tórax e o selo d''água no nível padronizado.","manter o frasco ao nível do tórax do paciente.","clampear o dreno durante o transporte por até 30 minutos, rotineiramente.","realizar a ordenha do tubo a cada 2 horas, rotineiramente.","manter o frasco ao nível do tórax para facilitar a leitura do débito."]'::jsonb, 0, 'Frasco acima do tórax permite refluxo; a ordenha rotineira não é recomendada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-446', 'enf', null, 'No paciente com hemorragia digestiva alta, um cuidado de enfermagem prioritário na admissão é:', '["garantir acessos venosos calibrosos, monitorizar sinais vitais e sinais de choque, e preparar para reposição volêmica e endoscopia.","oferecer dieta líquida imediatamente.","manter o paciente em decúbito dorsal horizontal sem monitorização.","administrar anti-inflamatório para dor.","liberar a deambulação sem acompanhamento."]'::jsonb, 0, 'Hematêmese e melena são sinais de sangramento digestivo alto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-447', 'enf', null, 'Na unidade de terapia intensiva, a avaliação da dor em pacientes intubados e incapazes de se comunicar deve utilizar:', '["escalas comportamentais validadas, como a BPS ou a CPOT.","apenas a escala numérica.","a escala de Braden.","a escala de Morse.","a escala de Apgar."]'::jsonb, 0, 'A dor não tratada aumenta agitação, consumo de oxigênio e tempo de internação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-448', 'enf', null, 'No paciente em uso de sonda vesical de demora há vários dias, a medida mais eficaz para prevenir a infecção urinária associada é:', '["avaliar diariamente a necessidade do cateter e retirá-lo o mais cedo possível.","trocar a sonda diariamente.","realizar irrigação vesical de rotina.","manter antibiótico profilático contínuo.","desconectar a sonda da bolsa para o banho."]'::jsonb, 0, 'O tempo de cateterização é o principal fator de risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-449', 'enf', null, 'Sobre a prevenção da pneumonia associada à ventilação mecânica, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-450', 'enf', null, 'No controle das infecções relacionadas à assistência, a vigilância epidemiológica realizada pela CCIH tem como objetivo:', '["conhecer a frequência e o perfil das infecções, identificar surtos e orientar as medidas de prevenção e controle.","punir os profissionais responsáveis pelas infecções.","substituir a higiene das mãos.","liberar o uso indiscriminado de antimicrobianos.","realizar apenas auditoria de contas."]'::jsonb, 0, 'Os indicadores são calculados por densidade de incidência (por 1.000 pacientes-dia ou dispositivos-dia).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-451', 'enf', null, 'No paciente com cateter venoso central, o curativo transparente semipermeável, quando íntegro e limpo, deve ser trocado a cada:', '["7 dias.","24 horas.","48 horas.","30 dias.","somente na retirada do cateter."]'::jsonb, 0, 'O curativo com gaze deve ser trocado a cada 48 horas; ambos devem ser trocados se estiverem úmidos, soltos ou sujos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-452', 'enf', null, 'O uso racional de antimicrobianos (stewardship) em hospitais tem como objetivos:', '["melhorar os desfechos clínicos, reduzir a resistência bacteriana, os eventos adversos e os custos.","aumentar o uso de antibióticos de amplo espectro.","prolongar os tratamentos.","dispensar culturas antes do tratamento.","substituir a CCIH."]'::jsonb, 0, 'Inclui a escolha adequada, a dose correta, a menor duração eficaz e o descalonamento guiado por culturas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-453', 'enf', null, 'No paciente em pós-operatório de cirurgia abdominal, uma intervenção de enfermagem para favorecer o retorno do peristaltismo é:', '["estimular a deambulação precoce, conforme liberação.","manter repouso absoluto prolongado.","restringir a analgesia.","manter o paciente em jejum indefinidamente.","aplicar compressas geladas no abdome."]'::jsonb, 0, 'A presença de ruídos hidroaéreos e a eliminação de flatos indicam retorno do trânsito intestinal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-454', 'enf', null, 'No paciente cirúrgico, a confirmação do sítio cirúrgico, do procedimento e da identidade do paciente, imediatamente antes da incisão, com a participação de toda a equipe, corresponde à etapa da lista de verificação da OMS denominada:', '["pausa cirúrgica (time out).","entrada (sign in).","saída (sign out).","admissão.","recuperação."]'::jsonb, 0, 'Na saída, confirmam-se o procedimento realizado, as contagens e a identificação de amostras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-455', 'enf', null, 'Ao avaliar uma ferida, o enfermeiro observa leito com tecido amarelado, úmido e aderido. Esse tecido corresponde a:', '["esfacelo, tecido desvitalizado que deve ser removido para favorecer a cicatrização.","tecido de granulação saudável.","tecido de epitelização.","necrose seca (escara).","hipergranulação."]'::jsonb, 0, 'Esfacelo e necrose atrasam a cicatrização e favorecem infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-456', 'enf', null, 'O enfermeiro avalia uma ferida com bordas maceradas pelo excesso de exsudato. A conduta adequada é:', '["escolher cobertura com maior capacidade de absorção e proteger a pele perilesional com barreira.","aplicar hidrogel para aumentar a umidade.","deixar a ferida exposta ao ar.","trocar o curativo apenas uma vez por semana, independentemente da saturação.","aplicar álcool nas bordas."]'::jsonb, 0, 'O manejo da umidade é um dos pilares do preparo do leito da ferida (TIME).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-457', 'enf', null, 'No paciente em ventilação mecânica com PaO2 baixa, uma das intervenções que pode ser discutida com a equipe para melhorar a oxigenação em casos graves de síndrome do desconforto respiratório agudo é:', '["a posição prona, conforme protocolo e com cuidados para prevenção de lesões.","a retirada da PEEP.","a redução da FiO2 para 21%.","a extubação imediata.","a manutenção do decúbito dorsal horizontal a 0°."]'::jsonb, 0, 'A prona exige equipe treinada, proteção de pontos de pressão e cuidado com dispositivos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-458', 'enf', null, 'No paciente com insuficiência cardíaca descompensada, o enfermeiro deve monitorar diariamente:', '["peso, balanço hídrico, sinais de congestão (dispneia, edema) e eletrólitos.","apenas a temperatura.","somente a glicemia.","apenas o nível de dor.","apenas a diurese, sem considerar o peso."]'::jsonb, 0, 'O ganho rápido de peso é sinal precoce de retenção hídrica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-459', 'enf', null, 'No preparo do paciente para alta hospitalar, uma prática que reduz readmissões é:', '["realizar orientações claras sobre medicamentos, sinais de alerta e cuidados em casa, com verificação da compreensão (teach-back) e articulação com a Atenção Básica.","entregar apenas a receita, sem orientação.","orientar apenas o acompanhante, sem envolver o paciente.","dispensar o contato com a Atenção Básica.","dar todas as orientações no momento da saída, de forma rápida."]'::jsonb, 0, 'A transição do cuidado é momento de risco para eventos adversos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-460', 'enf', null, 'Na unidade de terapia intensiva, o paciente com cateter arterial apresenta extremidade distal fria, pálida e com enchimento capilar lentificado. O enfermeiro deve:', '["comunicar imediatamente o médico, pela suspeita de comprometimento circulatório do membro.","aquecer o membro e manter a observação até o dia seguinte.","lavar o cateter com grande volume de soro.","elevar o membro e ignorar o achado.","aplicar torniquete acima do cateter."]'::jsonb, 0, 'A isquemia distal é complicação potencialmente grave do cateterismo arterial.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-461', 'enf', null, 'Na sala de recuperação pós-anestésica, a escala de Aldrete e Kroulik avalia:', '["atividade motora, respiração, circulação, consciência e saturação de oxigênio (ou coloração).","apenas a dor.","o risco de queda.","o risco de lesão por pressão.","a necessidade de dieta."]'::jsonb, 0, 'Pontuações elevadas (geralmente 8 a 10) indicam condições de alta da SRPA.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-462', 'enf', null, 'Durante a infusão de concentrado de plaquetas, o equipo utilizado deve:', '["ter filtro próprio para hemocomponentes e ser de uso exclusivo, sem compartilhamento com medicamentos ou outras soluções.","ser o mesmo da nutrição parenteral.","ser compartilhado com medicamentos.","ser usado sem filtro.","ser mantido em refrigeração junto com a bolsa."]'::jsonb, 0, 'As plaquetas são armazenadas em temperatura ambiente, sob agitação, e não devem ser refrigeradas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-463', 'enf', null, 'Na passagem de sonda nasogástrica, considerando a técnica e a verificação do posicionamento: I. A medida é feita do lóbulo da orelha até a ponta do nariz e, em seguida, até o apêndice xifoide. II. O teste de ausculta com injeção de ar é o padrão-ouro de confirmação. III. Antes de administrar a dieta, deve-se verificar o posicionamento da sonda. Está correto o que se afirma em:', '["I e III apenas.","I e II apenas.","I, II e III.","II apenas.","III apenas."]'::jsonb, 0, 'O padrão-ouro é a radiografia; a ausculta isolada não confirma a posição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-464', 'enf', null, 'A esterilização por vapor saturado sob pressão (autoclave gravitacional) de materiais termorresistentes, como instrumentais, tem como referência de parâmetros:', '["15 a 30 minutos a 121 °C e cerca de 1 atm (15 psi) acima da pressão atmosférica.","60 minutos a 100 °C e 1 atm.","45 a 60 minutos a 100 °C.","10 minutos a 134 °C e 2 atm, em autoclave gravitacional.","30 minutos a 121 °C e 0,5 atm."]'::jsonb, 0, 'Em autoclaves com pré-vácuo, ciclos a 134 °C têm tempo menor.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-465', 'enf', null, 'Na Atenção Básica, o enfermeiro avalia um usuário com manchas na pele e suspeita de hanseníase e conduz o caso conforme as recomendações da rede. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-466', 'enf', null, 'Na hanseníase, a avaliação do grau de incapacidade física deve ser realizada:', '["no momento do diagnóstico e na alta por cura, no mínimo, além de sempre que houver queixas neurológicas.","apenas na alta.","somente se o paciente relatar dor.","apenas em casos multibacilares.","somente após 5 anos de acompanhamento."]'::jsonb, 0, 'O grau varia de 0 a 2; a prevenção de incapacidades inclui autocuidado e acompanhamento neurológico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-467', 'enf', null, 'Na vigilância dos contatos de casos de hanseníase, recomenda-se:', '["realizar o exame dermatoneurológico dos contatos e avaliar a indicação da vacina BCG, conforme a presença de cicatriz vacinal.","iniciar a poliquimioterapia em todos os contatos.","isolar os contatos em domicílio.","apenas orientar, sem exame.","realizar baciloscopia em todos os contatos."]'::jsonb, 0, 'A BCG é indicada a contatos sem cicatriz ou com apenas uma cicatriz, conforme as normas do Ministério da Saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-468', 'enf', null, 'O eritema nodoso hansênico, caracterizado por nódulos dolorosos, febre e mal-estar, corresponde à:', '["reação hansênica tipo 2.","reação hansênica tipo 1.","recidiva da doença em todos os casos.","alergia à vacina BCG.","falha terapêutica obrigatória."]'::jsonb, 0, 'As reações podem ocorrer antes, durante ou após o tratamento e exigem manejo específico, sem interrupção da PQT.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-469', 'enf', null, 'Na investigação de contatos de tuberculose, a prova tuberculínica é considerada positiva, para fins de indicação do tratamento da infecção latente, quando a enduração for igual ou superior a:', '["5 mm.","15 mm.","2 mm.","20 mm.","1 mm."]'::jsonb, 0, 'Antes de tratar a infecção latente, é preciso excluir a tuberculose ativa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-470', 'enf', null, 'Paciente em tratamento para tuberculose relata urina alaranjada. O enfermeiro deve orientar que esse efeito:', '["é esperado com o uso da rifampicina e não indica suspensão do tratamento.","indica hepatite grave e exige suspensão imediata.","é causado pela isoniazida e indica intoxicação.","indica abandono do tratamento.","exige troca imediata do esquema."]'::jsonb, 0, 'A rifampicina também colore suor e lágrimas; já a isoniazida pode causar neuropatia periférica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-471', 'enf', null, 'No tratamento da tuberculose, considera-se abandono quando o paciente:', '["deixa de comparecer à unidade por mais de 30 dias consecutivos após a data prevista para o retorno ou para a tomada supervisionada.","falta a uma única consulta.","atrasa uma dose em 24 horas.","muda de endereço dentro do território.","apresenta efeitos adversos leves."]'::jsonb, 0, 'O tratamento diretamente observado e a busca ativa de faltosos reduzem o abandono.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-472', 'enf', null, 'No diagnóstico da infecção pelo HIV com testes rápidos, o fluxograma recomendado utiliza:', '["dois testes rápidos de fabricantes diferentes, realizados em sequência.","um único teste rápido.","apenas o teste de carga viral.","exclusivamente o exame de CD4.","teste rápido para sífilis."]'::jsonb, 0, 'Resultados discordantes seguem fluxograma específico, com nova testagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-473', 'enf', null, 'Segundo o Ministério da Saúde, a terapia antirretroviral (TARV) para pessoas vivendo com HIV é indicada:', '["para todas as pessoas, independentemente da contagem de linfócitos T CD4+.","apenas quando o CD4 estiver abaixo de 200 células/mm³.","somente em gestantes.","apenas após o surgimento de infecções oportunistas.","somente em pessoas com mais de 50 anos."]'::jsonb, 0, 'O tratamento precoce reduz a morbimortalidade e a transmissão (indetectável = intransmissível).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-474', 'enf', null, 'No acompanhamento pós-tratamento da sífilis adquirida, o monitoramento com teste não treponêmico (VDRL) deve ser:', '["trimestral no primeiro ano, considerando-se boa resposta a queda de pelo menos duas diluições em até 6 meses (sífilis recente).","apenas uma vez, 5 anos após o tratamento.","dispensado após a primeira dose de penicilina.","semanal por toda a vida.","realizado com teste treponêmico, que deve negativar."]'::jsonb, 0, 'O teste treponêmico costuma permanecer reagente; por isso não é usado para monitoramento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-475', 'enf', null, 'Na hepatite B, considera-se infecção crônica a persistência do HBsAg reagente por mais de:', '["6 meses.","15 dias.","1 mês.","10 anos.","48 horas."]'::jsonb, 0, 'A vacinação é a principal medida de prevenção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-476', 'enf', null, 'No manejo da dengue, segundo o Ministério da Saúde, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-477', 'enf', null, 'Na prova do laço para dengue em adultos, o manguito deve ser insuflado até o valor médio entre a pressão sistólica e a diastólica e mantido por:', '["5 minutos.","30 segundos.","15 minutos.","1 minuto.","10 minutos."]'::jsonb, 0, 'Em crianças, mantém-se por 3 minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-478', 'enf', null, 'Na fase aguda da chikungunya, enquanto não se descarta a dengue, o enfermeiro deve orientar:', '["evitar anti-inflamatórios não esteroides e ácido acetilsalicílico, utilizando analgésicos como paracetamol e dipirona, conforme prescrição.","o uso de ácido acetilsalicílico para dor articular.","repouso absoluto por 3 meses.","restrição de líquidos.","uso de corticoide por conta própria."]'::jsonb, 0, 'A dor articular pode persistir por meses na fase crônica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-479', 'enf', null, 'A leishmaniose tegumentar americana manifesta-se tipicamente como:', '["úlcera de pele indolor, arredondada, de bordas elevadas e fundo granuloso, em área exposta.","manchas hipocrômicas com perda de sensibilidade.","vesículas dolorosas em trajeto de nervo.","febre prolongada com aumento do baço, exclusivamente.","prurido noturno em dobras."]'::jsonb, 0, 'É transmitida por flebotomíneos; a forma visceral cursa com febre, emagrecimento e hepatoesplenomegalia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-480', 'enf', null, 'Segundo a legislação vigente de notificação compulsória, a tentativa de suicídio deve ser notificada:', '["de forma imediata (em até 24 horas) à Secretaria Municipal de Saúde.","apenas semanalmente.","somente se houver óbito.","apenas pelo psiquiatra.","somente com autorização da família."]'::jsonb, 0, 'A notificação imediata permite a articulação rápida da rede de cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-481', 'enf', null, 'Em um município com 10.000 habitantes, foram registrados 50 casos novos de uma doença em um ano. O coeficiente de incidência nesse período é de:', '["5 casos por 1.000 habitantes.","50 casos por 1.000 habitantes.","0,5 caso por 1.000 habitantes.","500 casos por 1.000 habitantes.","5 casos por 100 habitantes."]'::jsonb, 0, 'Incidência = (50 ÷ 10.000) × 1.000 = 5 por 1.000.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-482', 'enf', null, 'Em uma população de 2.000 pessoas, havia 100 pessoas com diabetes em determinado momento. A prevalência de diabetes nessa população é de:', '["5%.","2%.","20%.","0,5%.","50%."]'::jsonb, 0, 'Prevalência = casos existentes ÷ população = 100 ÷ 2.000 = 0,05 = 5%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-483', 'enf', null, 'O indicador de Swaroop-Uemura (razão de mortalidade proporcional) expressa:', '["a proporção de óbitos de pessoas com 50 anos ou mais em relação ao total de óbitos.","o número de nascidos vivos por mulher.","a proporção de óbitos maternos.","a incidência de doenças transmissíveis.","a cobertura vacinal."]'::jsonb, 0, 'Valores elevados indicam melhores condições de vida e saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-484', 'enf', null, 'A cobertura vacinal de uma vacina em determinado território é calculada pela razão entre:', '["o número de pessoas vacinadas com a dose indicada para o esquema completo e a população-alvo, multiplicado por 100.","o número de doses aplicadas e a população total do país.","o número de casos da doença e o número de vacinados.","o número de salas de vacina e de vacinadores.","o número de ESAVI e de doses aplicadas."]'::jsonb, 0, 'Coberturas abaixo das metas favorecem a reintrodução de doenças imunopreveníveis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-485', 'enf', null, 'Na vigilância epidemiológica, a busca ativa de casos caracteriza-se por:', '["a equipe procurar casos na comunidade ou nos serviços, em vez de aguardar que cheguem às notificações espontâneas.","aguardar as notificações enviadas pelos serviços.","notificar apenas os casos confirmados laboratorialmente.","registrar apenas óbitos.","realizar somente inquéritos telefônicos nacionais."]'::jsonb, 0, 'É útil em situações de surto e na investigação de contatos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-486', 'enf', null, 'A ocorrência de casos de uma doença relacionados entre si, em área geográfica restrita (como uma creche ou um bairro), acima do esperado, caracteriza:', '["um surto.","uma endemia.","uma pandemia.","uma prevalência pontual.","um caso esporádico."]'::jsonb, 0, 'O surto é uma epidemia localizada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-487', 'enf', null, 'Na vigilância de doenças, a "definição de caso" é importante porque:', '["padroniza os critérios clínicos, laboratoriais e epidemiológicos para classificar casos como suspeitos, prováveis ou confirmados.","substitui o exame físico.","dispensa a notificação.","serve apenas para fins de pesquisa.","é igual para todas as doenças."]'::jsonb, 0, 'Critérios padronizados permitem comparar dados entre diferentes locais e períodos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-488', 'enf', null, 'Durante a consulta de enfermagem a um usuário com hipertensão e diabetes, o enfermeiro avalia parâmetros clínicos, orienta o autocuidado e realiza a estratificação de risco. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-489', 'enf', null, 'Para a maioria dos adultos com diabetes mellitus tipo 2, a meta de hemoglobina glicada (HbA1c) recomendada é:', '["inferior a 7%.","inferior a 4%.","entre 10% e 12%.","superior a 9%.","não há meta definida."]'::jsonb, 0, 'As metas podem ser individualizadas, por exemplo, em idosos frágeis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-490', 'enf', null, 'Na pessoa com diabetes sem alterações nos pés, a avaliação completa dos pés deve ser realizada, no mínimo:', '["anualmente, com maior frequência conforme a classificação de risco.","a cada 10 anos.","somente quando surgirem feridas.","apenas no diagnóstico.","apenas por médico especialista."]'::jsonb, 0, 'A avaliação inclui inspeção, sensibilidade com monofilamento, pulsos e calçados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-491', 'enf', null, 'Durante o acompanhamento de um usuário com excesso de peso e fatores de risco cardiovascular, o enfermeiro investiga a síndrome metabólica. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-492', 'enf', null, 'O teste de Fagerström é utilizado, na abordagem do tabagista, para avaliar:', '["o grau de dependência à nicotina.","a função pulmonar.","o risco cardiovascular em 10 anos.","o nível de ansiedade.","o estado nutricional."]'::jsonb, 0, 'Ajuda a definir a necessidade de apoio farmacológico no tratamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-493', 'enf', null, 'O instrumento AUDIT é utilizado na Atenção Básica para:', '["identificar padrões de uso de álcool de risco e possível dependência.","rastrear depressão.","avaliar o risco de quedas em idosos.","avaliar a dependência de nicotina.","avaliar o desenvolvimento infantil."]'::jsonb, 0, 'Permite intervenções breves conforme a pontuação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-494', 'enf', null, 'O PHQ-9 é um questionário utilizado para:', '["rastrear e avaliar a gravidade de sintomas depressivos.","avaliar a cognição em idosos.","classificar o risco de lesão por pressão.","medir a dor crônica.","avaliar o uso de álcool."]'::jsonb, 0, 'Respostas positivas sobre pensamentos de morte exigem avaliação imediata do risco de suicídio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-495', 'enf', null, 'No atendimento a uma pessoa com ideação suicida na Atenção Básica, a conduta adequada inclui:', '["perguntar diretamente sobre o plano e o acesso a meios, elaborar com a pessoa um plano de segurança, envolver a rede de apoio e articular o cuidado com a rede de saúde mental.","evitar perguntar sobre suicídio para não induzir a ideia.","liberar a pessoa sem acompanhamento.","prometer sigilo absoluto em qualquer situação.","orientar a família a não falar sobre o assunto."]'::jsonb, 0, 'Perguntar sobre suicídio não aumenta o risco e é parte da avaliação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-496', 'enf', null, 'Em uma consulta na Atenção Básica, o enfermeiro recebe uma pessoa idosa com múltiplas queixas e perda gradual de independência nas atividades do cotidiano e realiza a avaliação multidimensional. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-497', 'enf', null, 'No fenótipo de fragilidade proposto por Fried, são critérios avaliados:', '["perda de peso não intencional, exaustão, fraqueza (força de preensão reduzida), lentidão da marcha e baixa atividade física.","pressão arterial, glicemia e colesterol.","número de filhos e renda familiar.","escolaridade e profissão.","visão, audição e paladar, exclusivamente."]'::jsonb, 0, 'A presença de três ou mais critérios caracteriza fragilidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-498', 'enf', null, 'O teste Timed Up and Go (TUG) é utilizado na avaliação da pessoa idosa para:', '["avaliar a mobilidade e o risco de quedas, cronometrando o tempo para levantar de uma cadeira, caminhar 3 metros, voltar e sentar.","avaliar a memória recente.","medir a força de preensão palmar.","rastrear depressão.","avaliar a acuidade visual."]'::jsonb, 0, 'Tempos aumentados indicam maior risco de queda e necessidade de intervenção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-499', 'enf', null, 'Considera-se polifarmácia, de forma geral, o uso concomitante de:', '["cinco ou mais medicamentos.","dois medicamentos.","um único medicamento de uso contínuo.","medicamentos fitoterápicos, apenas.","medicamentos prescritos por mais de um médico, independentemente do número."]'::jsonb, 0, 'A polifarmácia aumenta o risco de interações, efeitos adversos e quedas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-500', 'enf', null, 'Durante uma visita domiciliar, o enfermeiro acompanha um idoso de 78 anos com várias doenças crônicas, em uso de diferentes medicamentos e com episódios de esquecimento e instabilidade ao caminhar. Diante desses agravos, é correto afirmar:', '["a polifarmácia eleva o risco de interações e de quedas, exigindo a revisão periódica dos medicamentos.","a demência melhora com o aumento do número de medicamentos.","as quedas do idoso são esperadas do envelhecimento e acompanhadas apenas na consulta de rotina.","a incontinência urinária decorre do envelhecimento e não deve ser investigada.","a polifarmácia reduz o risco de quedas ao controlar várias doenças ao mesmo tempo."]'::jsonb, 0, 'Quedas e incontinência não são normais do envelhecimento e devem ser investigadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-501', 'enf', null, 'Durante uma ação na UBS, um homem de 55 anos manifesta preocupação com a possibilidade de câncer de próstata. Considerando as orientações aplicáveis ao rastreamento dessa neoplasia, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-502', 'enf', null, 'Na Atenção Básica, o enfermeiro atende um homem adulto e avalia suas necessidades de saúde, considerando a integralidade. Quanto à atuação profissional, é correto afirmar:', '["a consulta ao homem na Unidade Básica aborda a saúde sexual, a fertilidade e a prevenção.","a saúde reprodutiva do homem é assunto restrito à mulher no acompanhamento do casal.","a vasectomia é um método reversível que preserva a produção de espermatozoides após o procedimento, sem necessidade de orientação.","a investigação da fertilidade masculina só é indicada após dez anos de tentativas.","a prevenção de infecções no homem apoia-se apenas no exame periódico quando há parceria sexual fixa."]'::jsonb, 0, 'A vasectomia deve ser considerada método definitivo; a investigação de infertilidade é indicada após cerca de 1 ano de tentativas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-503', 'enf', null, 'No campo da saúde do trabalhador, a identificação de acidentes e de doenças relacionados ao trabalho envolve diferentes instrumentos de comunicação e notificação. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-504', 'enf', null, 'A perda auditiva induzida por ruído (PAIR), agravo relacionado ao trabalho, caracteriza-se por ser:', '["neurossensorial, geralmente bilateral, irreversível e progressiva com o tempo de exposição.","condutiva e reversível com repouso.","unilateral e aguda.","causada por infecção de ouvido.","exclusiva de trabalhadores com mais de 70 anos."]'::jsonb, 0, 'A prevenção inclui controle do ruído na fonte, proteção auditiva e monitoramento audiométrico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-505', 'enf', null, 'Durante a assistência domiciliar a pacientes com doenças ameaçadoras da vida, o enfermeiro participa da elaboração do plano de cuidados, promovendo o controle de sintomas e o apoio aos cuidadores. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-506', 'enf', null, 'Os cuidados paliativos visam aliviar o sofrimento e melhorar a qualidade de vida. O princípio fundamental dos cuidados paliativos é:', '["promover o alívio da dor e de outros sintomas, afirmando a vida e considerando a morte um processo natural, sem acelerá-la nem adiá-la.","suspender todos os tratamentos, incluindo hidratação e analgesia, quando o paciente for considerado fora de possibilidade terapêutica.","suspender todos os tratamentos de suporte quando a doença se torna irreversível, sem avaliação individual.","acelerar o processo de morte quando o tratamento curativo se torna fútil, mediante autorização familiar.","focar exclusivamente no suporte psicológico da família, delegando os sintomas físicos ao médico."]'::jsonb, 0, 'A eutanásia não faz parte dos cuidados paliativos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-507', 'enf', null, 'Na escada analgésica da Organização Mundial da Saúde, para dor moderada que não responde a analgésicos simples, recomenda-se:', '["opioide fraco (como tramadol ou codeína), associado ou não a analgésicos não opioides e adjuvantes.","suspender toda a analgesia.","iniciar sempre com morfina em altas doses.","usar apenas medidas não farmacológicas.","usar anti-inflamatório em doses crescentes sem limite."]'::jsonb, 0, 'Na dor intensa, utilizam-se opioides fortes; a via oral e os horários fixos são preferenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-508', 'enf', null, 'Na avaliação funcional de pacientes em cuidados paliativos, a escala que estima a capacidade de deambulação, a atividade, o autocuidado, a ingestão e o nível de consciência, expressa em porcentagem, é a:', '["Palliative Performance Scale (PPS).","escala de Braden.","escala de Glasgow.","escala de Morse.","escala de Apgar."]'::jsonb, 0, 'A PPS auxilia no planejamento do cuidado e na comunicação entre a equipe.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-509', 'enf', null, 'No processo de territorialização na Estratégia Saúde da Família, a microárea corresponde:', '["à área de atuação de um agente comunitário de saúde, com um conjunto de famílias sob sua responsabilidade.","ao território de todo o município.","à área de abrangência de um hospital.","à região de saúde.","ao conjunto de UBS de um distrito."]'::jsonb, 0, 'O mapeamento do território identifica riscos, vulnerabilidades e equipamentos sociais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-510', 'enf', null, 'No acolhimento à demanda espontânea na Atenção Básica (Caderno de Atenção Básica nº 28), a classificação de risco e vulnerabilidade orienta:', '["a definição de prioridades e do tipo de resposta, considerando o risco biológico e a vulnerabilidade, e não a ordem de chegada.","o atendimento exclusivamente por ordem de chegada.","a dispensa de usuários sem agendamento.","o encaminhamento de todos os casos para a UPA.","o atendimento apenas de casos crônicos agendados."]'::jsonb, 0, 'Situações agudas podem exigir atendimento imediato na própria UBS, com estabilização e transferência se necessário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-511', 'enf', null, 'No contexto da Atenção Primária, o sistema de informação que reúne os dados da produção e do cuidado registrados no e-SUS APS (Prontuário Eletrônico do Cidadão e Coleta de Dados Simplificada) é o:', '["Sistema de Informação em Saúde para a Atenção Básica (SISAB).","SINASC.","SIM.","SIH/SUS.","SINAN."]'::jsonb, 0, 'O SISAB substituiu o antigo SIAB.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-512', 'enf', null, 'No território da equipe, o enfermeiro observa a presença de vetores e de reservatórios de doenças e busca articular as ações de prevenção com o centro de controle de zoonoses. À luz dessas atribuições, é correto afirmar:', '["o centro de controle de zoonoses atua no controle das doenças transmitidas por animais à população.","a vigilância ambiental em saúde concentra sua atuação na inspeção dos estabelecimentos comerciais.","as ações do centro de controle de zoonoses limitam-se às doenças transmitidas entre seres humanos.","a vigilância da qualidade da água para consumo humano compete à vigilância epidemiológica municipal.","o controle de vetores é iniciado somente após a confirmação laboratorial dos casos."]'::jsonb, 0, 'A vigilância da água (VIGIAGUA) é atribuição da vigilância em saúde ambiental.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-513', 'enf', null, 'Durante a assistência a pacientes com doenças infecciosas, o enfermeiro considera a cadeia de transmissão. Assinale a alternativa correta.', '["A interrupção de um dos elos da cadeia de transmissão contribui para o controle da doença infecciosa.","O hospedeiro suscetível é aquele que elimina o agente e o transmite aos demais indivíduos sadios.","A via de transmissão corresponde ao ambiente em que o agente infeccioso se multiplica e se mantém.","A porta de entrada corresponde ao local em que o agente é eliminado do organismo do indivíduo doente.","O reservatório é a via pela qual o agente deixa o hospedeiro e alcança o ambiente."]'::jsonb, 0, 'Vacinação, tratamento, higiene e controle de vetores são exemplos de intervenções que interrompem a cadeia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-514', 'enf', null, 'Diante da notificação de casos de doenças transmissíveis no município, a equipe revisa as condutas de prevenção e as precauções a serem adotadas. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-515', 'enf', null, 'Ao acolher uma pessoa que relata exposição sexual de risco, o enfermeiro orienta sobre a prevenção combinada. No que se refere à profilaxia da infecção pelo HIV, é correto afirmar:', '["a profilaxia pós-exposição ao HIV (PEP) deve ser iniciada em até 72 horas após a exposição.","o tratamento da sífilis só é iniciado após o resultado dos dois testes, treponêmico e não treponêmico.","o teste rápido para HIV fornece o resultado em vários dias úteis.","o preservativo é substituído pela profilaxia pré-exposição na prevenção das demais IST.","a profilaxia pré-exposição é indicada após o contato de risco, para tratar a infecção já instalada."]'::jsonb, 0, 'Quanto mais precoce, melhor: idealmente nas primeiras 2 horas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-516', 'enf', null, 'Durante a assistência de enfermagem, o enfermeiro realiza a coleta de dados e a avaliação clínica do paciente para identificar necessidades e planejar cuidados individualizados. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-517', 'enf', null, 'Durante a assistência a pacientes que usam álcool e outras drogas, o enfermeiro pode adotar diferentes estratégias, conforme as diretrizes da atenção psicossocial. Assinale a alternativa correta.', '["A redução de danos busca diminuir os riscos do uso, ainda que o consumo permaneça.","O cuidado à pessoa que usa drogas é condicionado ao compromisso de interromper o consumo.","A distribuição de insumos de proteção estimula o aumento do consumo entre os usuários.","A redução de danos condiciona o cuidado à abstinência imediata.","A redução de danos é indicada apenas quando as demais estratégias se mostram ineficazes."]'::jsonb, 0, 'A redução de danos amplia o acesso e o vínculo, respeitando a autonomia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-518', 'enf', null, 'Diante de um aumento de casos febris no território durante o período de chuvas, a equipe investiga arboviroses. Analise: ( ) A dengue é transmitida pela picada do Aedes aegypti infectado. ( ) A dengue é transmitida de pessoa a pessoa pelo contato com secreções. ( ) A manutenção de criadouros de água parada reduz a proliferação do mosquito. ( ) A hidratação é medida importante no manejo da dengue. A sequência correta (V/F), de cima para baixo, é:', '["V, F, F, V.","V, V, F, F.","F, F, V, V.","V, F, V, V.","F, V, V, F."]'::jsonb, 0, 'É a eliminação (e não a manutenção) de criadouros que reduz a proliferação do mosquito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-519', 'enf', null, 'Durante as consultas de puericultura na Atenção Básica, a equipe utiliza a Caderneta da Criança. O registro das vacinas, do crescimento e do desenvolvimento na caderneta contribui para:', '["o acompanhamento longitudinal e a comunicação entre os serviços que atendem a criança.","substituir o prontuário da unidade.","dispensar as consultas de rotina.","registrar apenas as doenças da criança.","controlar a frequência escolar."]'::jsonb, 0, 'A caderneta fica com a família e deve ser apresentada em todos os atendimentos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-520', 'enf', null, 'Em um município, a equipe identifica aumento de agravos relacionados ao trabalho e planeja ações com base na Política Nacional de Saúde do Trabalhador e da Trabalhadora. Uma ação compatível com essa política é:', '["realizar a vigilância dos ambientes e processos de trabalho, articulada ao CEREST.","atender apenas trabalhadores com carteira assinada.","transferir todas as ações para a previdência social.","aguardar a ocorrência de óbitos para intervir.","restringir a notificação aos acidentes graves com afastamento superior a 15 dias."]'::jsonb, 0, 'A política inclui promoção, vigilância, assistência e informação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-521', 'enf', null, 'A dobutamina, droga vasoativa utilizada em pacientes com baixo débito cardíaco, tem como principal efeito:', '["inotrópico positivo (aumento da contratilidade cardíaca), podendo causar taquicardia e arritmias.","vasoconstrição intensa, como primeira escolha no choque séptico.","redução da frequência cardíaca como efeito principal.","efeito sedativo.","efeito diurético direto."]'::jsonb, 0, 'No choque séptico, o vasopressor de primeira escolha é a noradrenalina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-522', 'enf', null, 'Os efeitos da dopamina são dose-dependentes. Em doses elevadas, predomina o efeito:', '["alfa-adrenérgico, com vasoconstrição.","sedativo.","anticoagulante.","broncoconstritor.","hipoglicemiante."]'::jsonb, 0, 'Em doses intermediárias, predomina o efeito beta (inotrópico).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
